fn solve(n: i8) -> i8 {
    // For positive n, the alternating sum
    //   −1 + 2 − 3 + 4 − … up to n
    // has the closed‐form
    //   if n is even:  n/2
    //   if n is odd:   (n/2) − n
    // (integer division on positive n rounds down)
    if n % 2 == 0 {
        n / 2
    } else {
        (n / 2) - n
    }
}

